BEGIN TRANSACTION;
CREATE TABLE edges(revision TEXT NOT NULL REFERENCES revisions(hash),caller TEXT NOT NULL REFERENCES node_ids(id),callee TEXT NOT NULL REFERENCES node_ids(id),PRIMARY KEY(revision,caller,callee));
CREATE TABLE head(id INTEGER PRIMARY KEY CHECK(id=1),revision TEXT NOT NULL REFERENCES revisions(hash));
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE node_ids(module TEXT NOT NULL,name TEXT NOT NULL,id TEXT NOT NULL UNIQUE,PRIMARY KEY(module,name));
CREATE TABLE nodes(revision TEXT NOT NULL REFERENCES revisions(hash),id TEXT NOT NULL REFERENCES node_ids(id),hash TEXT NOT NULL,canonical TEXT NOT NULL,PRIMARY KEY(revision,id));
CREATE TABLE operation_functions(revision TEXT NOT NULL REFERENCES revisions(hash),function TEXT NOT NULL REFERENCES node_ids(id),content_hash TEXT NOT NULL,basis TEXT NOT NULL,PRIMARY KEY(revision,function));
CREATE TABLE operation_ids(id TEXT PRIMARY KEY,function TEXT NOT NULL REFERENCES node_ids(id),kind TEXT NOT NULL);
CREATE TABLE operation_versions(revision TEXT NOT NULL REFERENCES revisions(hash),function TEXT NOT NULL REFERENCES node_ids(id),path TEXT NOT NULL,parent TEXT NOT NULL,role TEXT NOT NULL,ordinal INTEGER NOT NULL,id TEXT NOT NULL REFERENCES operation_ids(id),kind TEXT NOT NULL,anchor TEXT NOT NULL,hash TEXT NOT NULL,site TEXT NOT NULL,PRIMARY KEY(revision,function,path),UNIQUE(revision,id),UNIQUE(revision,site));
CREATE TABLE revisions(hash TEXT PRIMARY KEY,module TEXT NOT NULL,source TEXT NOT NULL,path TEXT NOT NULL,created TEXT DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), language TEXT NOT NULL DEFAULT '0.1');
CREATE TABLE task_runs(id TEXT PRIMARY KEY,task TEXT NOT NULL,task_hash TEXT NOT NULL,status TEXT NOT NULL,report TEXT NOT NULL,report_hash TEXT NOT NULL,created TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
COMMIT;
